import React from 'react';
import { useAuth } from '../context/AuthContext';

const AuthDebug = () => {
  const { currentUser } = useAuth();
  
  // Only show in development
  if (process.env.NODE_ENV === 'production') {
    return null;
  }

  return (
    <div style={{ 
      position: '', 
      top: 10, 
      right: 10, 
      background: 'rgba(0,0,0,0.9)', 
      color: 'white', 
      padding: '10px', 
      borderRadius: '5px',
      fontSize: '12px',
      zIndex: 1000,
      fontFamily: 'monospace',
      maxWidth: '300px'
    }}>
      <div style={{ marginBottom: '5px', fontWeight: 'bold' }}>🔐 Auth Debug</div>
      <div>User: {currentUser ? currentUser.email : 'None'}</div>
      <div>Role: {currentUser ? currentUser.role : 'None'}</div>
      <div>ID: {currentUser ? currentUser.userId : 'None'}</div>
      <div>Token: {localStorage.getItem('token') ? '✅ Exists' : '❌ Missing'}</div>
      <div>UserID: {localStorage.getItem('userId') || 'None'}</div>
    </div>
  );
};

export default AuthDebug;
